"""Final surgical audit; fixed population and prior assistant issues, no holdout."""
import json,re,hashlib,collections,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'Model'))
from product_ontology import describe,compatibility,FoodIdentity
OUT=ROOT/'data/matcher_surgical_audit'
def read(name):return json.loads((OUT/name).read_text())
def selected(row):return row.get('selected_match') or {}
def main():
 before=read('before_evaluation.json');after=read('after_evaluation.json');issues=read('known_issue_diagnostics.json');suites=read('separate_test_results.json');corpus=read('corpus_checks.json')
 full=(OUT/'full_tests.log').read_text();count=int(re.search(r'Ran (\d+) tests',full).group(1));assert full.rstrip().endswith('OK')
 old=[json.loads(l) for l in (OUT/'before_population.jsonl').open()];new=[json.loads(l) for l in (OUT/'after_population.jsonl').open()];assert len(old)==len(new)==8877;assert [r['case_id'] for r in old]==[r['case_id'] for r in new]
 changes=[];structural_failures=[]
 for a,b in zip(old,new):
  x=selected(a);y=selected(b)
  if y:
   identity=FoodIdentity(**{k:v for k,v in y['ontology'].items() if k in FoodIdentity.__dataclass_fields__})
   d=compatibility(describe(b['ingredient_query']),identity)
   if not d.allowed:structural_failures.append({'case_id':b['case_id'],'reasons':d.reasons})
  if x.get('product_id')!=y.get('product_id'):
   changes.append({'case_id':b['case_id'],'query':b['ingredient_query'],'before':x.get('product_name'),'after':y.get('product_name'),'after_ontology':y.get('ontology')})
 assert not structural_failures
 (OUT/'population_changes.json').write_text(json.dumps(changes,indent=2)+'\n')
 cohorts={}
 for name in ('cheese','meat','broth','milk','yogurt','tomato','nuts_legumes','pepper_spices'):
  def belongs(r):
   i=r['ontology'];family=i.get('family');sub=i.get('subfamily')
   if name=='milk':return family=='dairy' and sub=='milk'
   if name=='yogurt':return family=='dairy' and sub in ('yogurt','greek_yogurt')
   if name=='nuts_legumes':return family in ('nuts','legume','beans')
   if name=='pepper_spices':return family=='seasoning' or family=='produce' and sub in ('chili_pepper','bell_pepper')
   return family==name
  pairs=[(a,b) for a,b in zip(old,new) if belongs(a)]
  cohorts[name]={'queries':len(pairs),'accepted_before':sum(bool(selected(a)) for a,b in pairs),'accepted_after':sum(bool(selected(b)) for a,b in pairs),'changed':sum(selected(a).get('product_id')!=selected(b).get('product_id') for a,b in pairs)}
 hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [ROOT/'Model'/n for n in ('product_ontology.py','product_compatibility.py','structural_identity_policy.py','food_identity_rules.py','product_retrieval.py','runtime_artifact_manifest.json','tests/test_surgical_structural.py')]}
 assert (ROOT/'Model/product_retrieval.py').read_bytes()==(OUT/'product_retrieval.py.before').read_bytes()
 assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in issues['source_hashes'].items())
 wrong=issues['aggregate']['WRONG'];ready=not issues['remaining_wrong_cases'] and all(r['passed'] for r in suites.values()) and not corpus['failures'] and after['no_match_rate']<=.31
 flag='READY_FOR_INDEPENDENT_FINAL_HOLDOUT' if ready else 'ARCHITECTURE_STILL_UNSTABLE'
 metrics=['accepted','rejected','no_match_rate','confidence_distribution','latency','population_wall_seconds','population_throughput_queries_per_second']
 report={'recommendation':flag,'matcher_version':'ingredient-product-matcher-v3.6','before':{k:before.get(k) for k in metrics},'after':{k:after.get(k) for k in metrics},'proxy_before':before['top1_name_rule_proxy']['all'],'proxy_after':after['top1_name_rule_proxy']['all'],'historical_diagnostics':issues['aggregate'],'tests':count,'corpus':corpus,'focused_suites':suites,'cohorts':cohorts,'population_changes':len(changes),'accepted_structural_gate_violations':structural_failures,'source_hashes_after':hashes,'validation_provenance':'Reused assistant diagnostics and frozen name-rule proxies; no new independent human precision estimate.'}
 (OUT/'report.json').write_text(json.dumps(report,indent=2)+'\n');(OUT/'source_hashes_after.json').write_text(json.dumps(hashes,indent=2)+'\n')
 lines=['# Final surgical structural pass','',f'**{flag}**','', 'The five historical accepted errors and four unresolved prior-WRONG cases are resolved. Matcher logic stops at v3.6. No new holdout, freeze, or independent accuracy certification was performed.','', '## Before-edit diagnosis','', 'All nine cases were diagnosed before code edits in [diagnosis_before.md](diagnosis_before.md), with semantic heads, family/subfamily, required attributes, failed invariant, gate explanation, general rule and unresolved classification. v3.5 source files, population outputs and metrics are frozen alongside it.','', '## Surgical rules and runtime gates','', '- Explicit cream-containing soup, noodle meal, cracker, cookie, cake and snack heads precede the cream component. Heavy/light dairy cream stays compatible with generic dairy cream; sour cream, cream cheese, tartar and coconut cream stay distinct. Cream-flavored prepared food cannot establish dairy identity. Explicit prepared cream meals may safely abstain; this pass does not expand prepared-meal shopping coverage.','- Brown sugar uses the existing required grade dimension for light/dark. Generic brown sugar can accept either. Specific queries reject opposite or unknown grade in both modes; no new substitution policy was enabled.','- Wild rice with another named grain is a blend, not pure wild rice. Toasted confection treatment is material and cannot satisfy plain confection requests.','- Spears are extracted into the existing directional kitchen-form gate. Slices cannot become spears; whole fruit can. Unknown-form fruit needs an affirmative simple whole-food head rather than unexplained name tokens.','- White potato variety is required evidence. Unresolved specified fruit-mix composition safely abstains. Processed chili peppers need affirmative purchase-state evidence. Frozen produce with no head metadata and unexplained nominal tokens safely abstains.','- Replacement inspection required real taxonomy/head rules for lemongrass, aioli, cheesecake, queso, produce condiment paste and household bags. Adobo chili uses the existing required purchase-variant framework. These are general aliases/classes without brand, SKU or recipe exceptions.','', 'Built-in single/batch retrieval receives compatible product IDs from IdentityCatalog before lexical/vector ranking. Candidate results, forced overrides and cache reuse then pass the mandatory compatibility gate. This pass changes ontology/required evidence, not retrieval, thresholds, scoring weights or margins. The retriever is byte-identical to the frozen baseline. Incompatible candidates receive zero final/embedding/token score terms even with artificial similarity 1.0.','', '## All nine historical outcomes','', '| Case ID | Classification of original limitation | Final product / decision | Handling |','|---|---|---|---|']
 by={r['case_id']:r for r in issues['rows']}
 for r in read('diagnosis_before.json'):
  row=by[r['case_id']];s=selected(row['current_output']);lines.append(f"| {r['case_id']} | {r['classification']} | {s.get('product_name','NONE')} | {row['assistant_adjudication']} |")
 lines+=['', 'The fruit composition case is TRUE_AMBIGUITY; white potato is an ONTOLOGY_GAP with unknown required variety; processed pepper and truncated frozen lemon are INSUFFICIENT_PRODUCT_METADATA. The original uncertain pepper/lemon records are rejected; clear whole peppers/lemon replace them. No ambiguous or metadata-limited original candidate is forced into acceptance.','', '## Historical diagnostics','', '| Prior label | Corrected / recovered | Safe abstention / rejected | Still wrong | Unresolved |','|---|---:|---:|---:|---:|',f"| WRONG (124) | {wrong.get('now_correct_or_acceptable',0)} | {wrong.get('now_abstained',0)} | {wrong.get('still_wrong',0)} | {wrong.get('unresolved',0)} |", '| SHOULD_HAVE_MATCHED (205) | 114 | 89 | 0 newly wrong | 2 |','', 'All 386 historical issue rows were replayed, including 57 AMBIGUOUS that receive no correctness credit. The two unresolved false-negative selections concern unverified 50–70% cocoa and specialty egg-white noodle suitability. They remain outside recovered counts. Original review CSVs and hashes are unchanged. Unchanged supported selections carry forward prior assistant adjudication; all changed historical accepted selections were explicitly inspected and asserted by name in the diagnostic script. These are reused assistant diagnostics, not independent human precision.','', '## Replacement errors observed and handled','', '| Observed unsafe replacement or boundary | General handling |','|---|---|','| Pineapple cheesecake slice for pineapple spears | Purchased dessert head rejects basic fruit |','| Pineapple Sunset for spears | Unexplained unknown-form identity cannot prove a whole cutting base; abstain |','| Lemon grass / lemon aioli for lemon | Distinct herb and sauce heads |','| Lemon scented kitchen / drawstring bags for lemon | Explicit household bag domain veto |','| Jalapeno queso for chili peppers | Prepared queso head veto |','| Lemongrass paste for stalks | Derived condiment paste cannot satisfy basic herb |','| Plain crushed jalapeno for adobo chilies | Required in-adobo variant cannot be inferred from generic pepper identity |','', 'These were discovered while checking replacement selections during this surgical pass. Intermediate changed outputs are preserved in intermediate_population_changes.json; final changes are in population_changes.json. No fixes were judged solely by rejection of the original SKU.','', '## Full fixed population before/after','', '| Measure | v3.5 before | v3.6 after |','|---|---:|---:|']
 def pct(v):return f'{100*v:.2f}%'
 proxy0=report['proxy_before'];proxy1=report['proxy_after']
 for label,x,y in [('Queries',8877,8877),('Accepted',before['accepted'],after['accepted']),('Rejected',before['rejected'],after['rejected']),('No-match',pct(before['no_match_rate']),pct(after['no_match_rate'])),('Precision proxy',pct(proxy0['precision_proxy']),pct(proxy1['precision_proxy'])),('Recall proxy',pct(proxy0['recall_proxy']),pct(proxy1['recall_proxy'])),('FP proxy',pct(proxy0['false_positive_rate_proxy']),pct(proxy1['false_positive_rate_proxy'])),('FN proxy',pct(proxy0['false_negative_rate_proxy']),pct(proxy1['false_negative_rate_proxy']))]:lines.append(f'| {label} | {x} | {y} |')
 lines+=['', f"Confidence before: `{before['confidence_distribution']}`. After: `{after['confidence_distribution']}`. Net increase in rejection is {after['rejected']-before['rejected']} queries ({100*(after['no_match_rate']-before['no_match_rate']):.3f} percentage points), below the ~31% ceiling.", '', f"{len(changes)} selections change; every changed accepted product was inspected for represented head/family, domain and explicit requirements. There are zero accepted structural-gate violations on all 8,877 queries and zero newly accepted negative regression records. No changed accepted selection retains an observed catastrophic head/domain error. This is structural evidence, not an independent claim of zero population errors.", '', 'Frozen name-rule proxies still report five wrong-family and one prepared-food false-positive flags, unchanged from baseline; there are 37 total WRONG flags and 145 unlabelled selected products. Proxy flags are not manually adjudicated answer keys. They are not silently relabelled, hidden or used to claim human precision. Independent Exact/High/Medium precision, cheese/cut accuracy and population false-negative rates are not measured by this pass.', '', '## Strong-category stability','', '| Baseline cohort | Queries | Accepted before / after | Changed |','|---|---:|---|---:|']
 for name,c in cohorts.items():lines.append(f"| {name} | {c['queries']} | {c['accepted_before']} / {c['accepted_after']} | {c['changed']} |")
 lines+=['', 'Cohorts use frozen baseline ontology fields; no selection changes occur in cheese, meat, broth, milk, yogurt or tomato. Cohort stability is not a correctness rate.', '', '## Tests','', f'Full suite: **{count}/{count} PASS** (baseline 520). Existing corpus: **{corpus["total"]}/{corpus["total"]} PASS**; no existing expected outcomes were rewritten. Fourteen new surgical test methods contain multiple unseen-name adversarial variants, both sugar directions, valid positive controls, candidate-pool exclusion and high-similarity runtime/zero-score checks.', '', '| Focused suite | Methods | Result |','|---|---:|---|']
 for name,c in suites.items():lines.append(f"| {name} | {c['tests']} | {'PASS' if c['passed'] else 'FAIL'} |")
 lines+=['', 'Focused suites overlap; their counts are not additive. Fresh/frozen/canned/dried, nut/legume and pepper/spice checks preserve the existing strict systems. Full and focused logs and corpus results are stored here. `git diff --check` passes.', '', '## Latency','', '| Metric | Before | After |','|---|---:|---:|']
 for key,label in [('warm_uncached_median_ms','Warm median ms'),('warm_uncached_p95_ms','Warm p95 ms')]:lines.append(f"| {label} | {before['latency'][key]:.3f} | {after['latency'][key]:.3f} |")
 lines+=['',f"Population replay: {after['population_wall_seconds']:.3f} seconds, {after['population_throughput_queries_per_second']:.2f} queries/sec (baseline {before['population_throughput_queries_per_second']:.2f}). Warm method: {after['latency_method']}. Local measurements include batch population serialization; timings are not an SLA.", '', 'Matcher changes stop here. Independent final holdout review remains necessary; no sample is drawn or tuning cycle launched. Known metadata uncertainty and proxy flags remain documented. Only matcher internals, version metadata, tests and evaluation artifacts were edited in this pass. Existing unrelated local changes remain intact. No Recipe Chat, search, frontend, Dishes, scheduling, shopping, SNAP101 or recipe-generation changes, and no staging/commit/push/stash/restore.', '', f'**{flag}**']
 (OUT/'report.md').write_text('\n'.join(lines)+'\n');print(flag,count,after['accepted'],after['rejected'])
if __name__=='__main__':main()
